import {makeNumberRound} from '../logic.js';import {gameFrame,roundFlow} from '../ui.js';
export function mountGame(root,c){const flow=roundFlow(root,c);function next(){flow.next();const r=makeNumberRound(c.difficulty),selected=new Set();const area=gameFrame(root,'Make the target','Select a combination of numbers, then check your sum.');area.innerHTML=`<div class="target-number"><span>Target sum</span><strong>${r.target}</strong></div><div class="number-grid">${r.numbers.map((n,i)=>`<button class="number-tile" data-i="${i}" aria-pressed="false">${n}</button>`).join('')}</div><div class="answer-row"><span id="sum">Your sum: 0</span><button class="primary" id="submit">Check sum</button></div>`;area.querySelectorAll('[data-i]').forEach(b=>b.onclick=()=>{const i=+b.dataset.i;selected.has(i)?selected.delete(i):selected.add(i);b.setAttribute('aria-pressed',selected.has(i));area.querySelector('#sum').textContent='Your sum: '+[...selected].reduce((n,j)=>n+r.numbers[j],0);});area.querySelector('#submit').onclick=()=>{const sum=[...selected].reduce((n,j)=>n+r.numbers[j],0);flow.answer(selected.size>0&&sum===r.target,`One solution: ${r.solution.map(i=>r.numbers[i]).join(' + ')} = ${r.target}.`,next);};}next();return {dispose(){}};}
